// SPDX-License-Identifier: AGPL-3.0-or-later
// Generates shared/public-suffix-snapshot.ts from the Public Suffix List.
// Usage: node scripts/generate-public-suffix-snapshot.mjs [path-to-public_suffix_list.dat]
// With no path it downloads https://publicsuffix.org/list/public_suffix_list.dat.
// The list is MPL-2.0 (https://mozilla.org/MPL/2.0/); the generated file carries the notice.
import { readFileSync, writeFileSync } from "node:fs";
import { domainToASCII } from "node:url";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const arg = process.argv[2];
const text = arg ? readFileSync(arg, "utf8") : await (await fetch("https://publicsuffix.org/list/public_suffix_list.dat")).text();
const version = /VERSION:\s*(\S+)/.exec(text)?.[1] ?? "unknown";
const commit = /COMMIT:\s*(\S+)/.exec(text)?.[1] ?? "unknown";
const rules = new Set(), wild = new Set(), except = new Set();
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line || line.startsWith("//")) continue;
  const rule = line.split(/\s+/)[0];
  const bang = rule.startsWith("!");
  const star = rule.startsWith("*.");
  const body = domainToASCII(rule.replace(/^(!|\*\.)/, "")).toLowerCase();
  if (!body) continue;
  (bang ? except : star ? wild : rules).add(body);
}
const fmt = set => JSON.stringify([...set].sort()).replace(/","/g, '", "');
const out = `// SPDX-License-Identifier: MPL-2.0
// GENERATED by scripts/generate-public-suffix-snapshot.mjs. Do not edit by hand.
// Source: the Public Suffix List (https://publicsuffix.org), version ${version}, commit ${commit}.
// The Public Suffix List is licensed under the Mozilla Public License 2.0
// (https://mozilla.org/MPL/2.0/). This file is a data derivative of it and stays under MPL-2.0 for that data.
// Rules are stored as punycode (ASCII) labels. ICANN and private sections are both included.
export const PUBLIC_SUFFIX_SNAPSHOT_VERSION = ${JSON.stringify(version)};
/** Plain rules, e.g. "co.uk". */
export const PSL_RULES: readonly string[] = ${fmt(rules)};
/** Wildcard rules without the "*." prefix, e.g. "ck" for "*.ck". */
export const PSL_WILDCARDS: readonly string[] = ${fmt(wild)};
/** Exception rules without the "!" prefix, e.g. "www.ck". */
export const PSL_EXCEPTIONS: readonly string[] = ${fmt(except)};
`;
const target = join(dirname(fileURLToPath(import.meta.url)), "..", "shared", "public-suffix-snapshot.ts");
writeFileSync(target, out);
console.log(`wrote ${target}: ${rules.size} rules, ${wild.size} wildcards, ${except.size} exceptions (PSL ${version})`);
